declare(strict_types=1);

namespace Dataphyre\Panel;

/**
 * Durable signal -> proposal -> approval -> command -> outcome feedback loop.
 *
 * Command inputs, proposer identities, idempotency keys, and approval
 * attestations are encrypted at rest. Public projections contain only bounded
 * summaries and one-way identity hashes.
 */
final class PanelClosedLoopIntelligence implements \JsonSerializable {
	private readonly PanelAtomicSnapshotStore $store;
	private readonly \Closure $clock;
	/** @var array<string,string> */private readonly array $keys;
	/** @var array<string,int> */private readonly array $approvalThresholds;

	/**
	 * @param array<string,string> $trustedKeys
	 * @param array<string,int> $approvalThresholds
	 */
	public function __construct(
		string $root,
		private readonly PanelCommandFabric $fabric,
		private readonly PanelPolicyControlPlane $policy,
		private readonly PanelCommandPayloadCodec $codec,
		array $trustedKeys,
		private readonly string $currentKeyId,
		array $approvalThresholds=[],
		?callable $clock=null,
		private readonly int $snapshotRetention=2048,
		private readonly int $approvalTtlSeconds=3600,
		private readonly int $dispatchStaleSeconds=300,
		private readonly int $maximumEntries=10000,
	){
		if($fabric->policy()!==$policy){throw new \InvalidArgumentException('Closed-loop intelligence and command fabric must share one policy control plane.');}
		$keys=[];foreach($trustedKeys as$id=>$key){$id=PanelOperationsGuard::name((string)$id,'intelligence trust key id');if(!is_string($key)||strlen($key)<32){throw new \InvalidArgumentException('Intelligence trust keys require at least 32 bytes.');}$keys[$id]=$key;}
		if(!isset($keys[$currentKeyId])){throw new \InvalidArgumentException('The current intelligence trust key is unavailable.');}$this->keys=$keys;
		$defaults=['low'=>0,'medium'=>1,'high'=>2,'critical'=>2];$thresholds=[];foreach($defaults as$risk=>$default){$value=$approvalThresholds[$risk]??$default;if(!is_int($value)||$value<0||$value>16){throw new \InvalidArgumentException('Intelligence approval thresholds must be integers between zero and sixteen.');}$thresholds[$risk]=$value;}if(array_diff(array_keys($approvalThresholds),array_keys($defaults))!==[]){throw new \InvalidArgumentException('Intelligence approval threshold risk is invalid.');}$this->approvalThresholds=$thresholds;
		if($snapshotRetention<8||$approvalTtlSeconds<60||$approvalTtlSeconds>604800||$dispatchStaleSeconds<0||$dispatchStaleSeconds>604800||$maximumEntries<100||$maximumEntries>1000000){throw new \InvalidArgumentException('Closed-loop intelligence retention or timing bounds are invalid.');}
		$this->clock=$clock!==null?\Closure::fromCallable($clock):static fn():string=>gmdate('c');
		$initial=$this->signedState(['schema'=>'panel_closed_loop_intelligence','version'=>1,'revision'=>0,'signals'=>[],'proposals'=>[],'feedback'=>[],'idempotency'=>['proposals'=>[],'feedback'=>[]]]);
