	}

	public function fabric():PanelCommandFabric{return$this->fabric;}
	public function policy():PanelPolicyControlPlane{return$this->policy;}
	public function store():PanelAtomicSnapshotStore{return$this->store;}

	/** @param array<string,mixed> $evidence */
	public function issueSignal(string $kind,string $tenantId,string $source,string $subjectType,string|int $subjectId,string $summary,string $severity,int $confidenceBasisPoints,array $evidence=[],string|int|\DateTimeInterface|null $observedAt=null,int $ttlSeconds=900):PanelIntelligenceSignal {
		if($ttlSeconds<30||$ttlSeconds>604800){throw new \InvalidArgumentException('Intelligence signal TTL is invalid.');}$observedAt=PanelOperationsGuard::instant($observedAt??$this->now());$expiresAt=$this->after($observedAt,$ttlSeconds);return PanelIntelligenceSignal::sign($kind,$tenantId,$source,$subjectType,$subjectId,$summary,$severity,$confidenceBasisPoints,$evidence,$observedAt,$expiresAt,$this->currentKeyId,$this->keys[$this->currentKeyId]);
	}

	public function recordSignal(PanelIntelligenceSignal $signal,PanelPolicyRequest|array $request):PanelIntelligenceSignal {
		$request=$this->request($request);$this->assertTenant($request,$signal->tenantId());$this->authorize($request,'intelligence.signal.record',$signal->tenantId(),'intelligence_signal',$signal->id(),$this->riskForSeverity($signal->severity()),['kind'=>$signal->kind(),'source'=>$signal->source(),'severity'=>$signal->severity(),'confidence_basis_points'=>$signal->confidenceBasisPoints()]);
