		$result=$this->mutate(function(array &$state)use($signal,$stored):array{$existing=$state['signals'][$signal->id()]??null;if(is_array($existing)){if(!hash_equals($this->storedSignal($existing)->digest(),$signal->digest())){throw new \LogicException('Intelligence signal identity conflict.');}return$existing;}if(count($state['signals'])>=$this->maximumEntries){throw new \LengthException('Intelligence signal retention limit is reached.');}$state['signals'][$signal->id()]=$stored;ksort($state['signals'],SORT_STRING);return$state['signals'][$signal->id()];},'intelligence.signal.recorded',['signal_id'=>$signal->id(),'tenant_id'=>$signal->tenantId(),'kind'=>$signal->kind()]);return$this->storedSignal($result);
	}

	/** @param array<string,mixed> $evidence */
	public function observe(string $kind,string $tenantId,string $source,string $subjectType,string|int $subjectId,string $summary,string $severity,int $confidenceBasisPoints,PanelPolicyRequest|array $request,array $evidence=[],string|int|\DateTimeInterface|null $observedAt=null,int $ttlSeconds=900):PanelIntelligenceSignal {return$this->recordSignal($this->issueSignal($kind,$tenantId,$source,$subjectType,$subjectId,$summary,$severity,$confidenceBasisPoints,$evidence,$observedAt,$ttlSeconds),$request);}

	/** @param array<string,mixed> $input */
	public function propose(string $signalId,string $command,string $ability,array $input,string $risk,string $reason,PanelPolicyRequest|array $request,string $idempotencyKey,int $requestedApprovals=0,?int $expectedRevision=null):PanelIntelligenceProposal {
		$request=$this->request($request);$signal=$this->signal($signalId);$this->assertTenant($request,$signal->tenantId());$risk=strtolower(trim($risk));if(!isset($this->approvalThresholds[$risk])||$requestedApprovals<0||$requestedApprovals>16||($expectedRevision!==null&&$expectedRevision<0)){throw new \InvalidArgumentException('Intelligence proposal risk, approval count, or expected revision is invalid.');}$command=PanelOperationsGuard::name($command,'intelligence proposal command',160);PanelOperationsGuard::abilityPatterns([$ability],'intelligence proposal ability');$input=PanelOperationsGuard::object($input,'intelligence proposal input',4096);PanelOperationsGuard::canonical($input);$reason=PanelOperationsGuard::label($reason,'intelligence proposal reason',2048);$idempotencyHash=$this->idempotency($signal->tenantId(),$request->actorId(),$idempotencyKey,'proposal');
		$decision=$this->authorize($request,'intelligence.proposal.create',$signal->tenantId(),'intelligence_signal',$signal->id(),$risk,['signal_kind'=>$signal->kind(),'signal_severity'=>$signal->severity(),'command'=>$command,'command_ability'=>$ability]);$required=max($requestedApprovals,$this->approvalThresholds[$risk],$decision->approvalCount());$inputDigest=PanelOperationsGuard::digest($input);$fingerprint=PanelOperationsGuard::digest(['signal_id'=>$signal->id(),'signal_digest'=>$signal->digest(),'command'=>$command,'ability'=>$ability,'input_digest'=>$inputDigest,'risk'=>$risk,'reason'=>$reason,'required_approvals'=>$required,'expected_revision'=>$expectedRevision]);
