		$result=$this->mutate(function(array &$state)use($proposal,$sealed,$idempotencyHash,$fingerprint):array{$known=$state['idempotency']['proposals'][$idempotencyHash]??null;if(is_array($known)){if(!hash_equals((string)($known['fingerprint']??''),$fingerprint)){throw new \LogicException('Intelligence proposal idempotency key conflict.');}return$state['proposals'][(string)$known['id']]['manifest'];}if(count($state['proposals'])>=$this->maximumEntries){throw new \LengthException('Intelligence proposal retention limit is reached.');}$state['proposals'][$proposal->id()]=['manifest'=>$proposal->jsonSerialize(),'sealed'=>$sealed,'idempotency_hash'=>$idempotencyHash,'fingerprint'=>$fingerprint,'approvals'=>[],'dispatch'=>null,'feedback_ids'=>[]];$state['idempotency']['proposals'][$idempotencyHash]=['id'=>$proposal->id(),'fingerprint'=>$fingerprint];ksort($state['proposals'],SORT_STRING);ksort($state['idempotency']['proposals'],SORT_STRING);return$proposal->jsonSerialize();},'intelligence.proposal.created',['proposal_id'=>$proposal->id(),'signal_id'=>$signal->id(),'tenant_id'=>$signal->tenantId(),'command'=>$command,'risk'=>$risk]);return PanelIntelligenceProposal::hydrate($result);
	}

	public function approve(string $proposalId,PanelPolicyRequest|array $request,?int $ttlSeconds=null):PanelIntelligenceApproval {
		$request=$this->request($request);$proposal=$this->proposal($proposalId);$this->assertTenant($request,$proposal->tenantId());$this->authorize($request,'intelligence.proposal.approve',$proposal->tenantId(),'intelligence_proposal',$proposal->id(),$proposal->risk(),['command'=>$proposal->command(),'signal_id'=>$proposal->signalId()]);if($proposal->terminal()||$proposal->status()==='dispatching'){throw new \LogicException('Intelligence proposal can no longer be approved.');}$private=$this->proposalPrivate($proposal);if(hash_equals((string)$private['proposer_id'],$request->actorId())){throw new \LogicException('Intelligence proposal authors cannot approve their own proposal.');}$ttl=$ttlSeconds??$this->approvalTtlSeconds;if($ttl<60||$ttl>604800){throw new \InvalidArgumentException('Intelligence approval TTL is invalid.');}$now=$this->now();$approval=PanelIntelligenceApproval::sign($proposal,$request->actorId(),$now,$this->after($now,$ttl),$this->currentKeyId,$this->keys[$this->currentKeyId]);$hash=$approval->approverHash();
