	public function reject(string $proposalId,string $reason,PanelPolicyRequest|array $request):PanelIntelligenceProposal {
		$request=$this->request($request);$proposal=$this->proposal($proposalId);$this->assertTenant($request,$proposal->tenantId());$this->authorize($request,'intelligence.proposal.reject',$proposal->tenantId(),'intelligence_proposal',$proposal->id(),$proposal->risk(),['command'=>$proposal->command(),'signal_id'=>$proposal->signalId()]);$reason=PanelOperationsGuard::label($reason,'intelligence rejection reason',1024);
		$result=$this->mutate(function(array &$state)use($proposal,$request,$reason):array{$entry=&$this->proposalEntry($state,$proposal->id());$current=PanelIntelligenceProposal::hydrate($entry['manifest']);if($current->revision()!==$proposal->revision()){throw new \LogicException('Intelligence proposal changed before rejection could be committed.');}if($current->terminal()||$current->status()==='dispatching'){throw new \LogicException('Intelligence proposal can no longer be rejected.');}$rejection=['reason'=>$reason,'actor_hash'=>hash('sha256',$request->actorId()),'rejected_at'=>$this->now()];$entry['manifest']=$current->evolve('rejected',$current->approverHashes(),$current->revision()+1,$current->dispatchAttempts(),$current->feedbackCount(),$this->now(),null,$rejection)->jsonSerialize();return$entry['manifest'];},'intelligence.proposal.rejected',['proposal_id'=>$proposal->id(),'tenant_id'=>$proposal->tenantId()]);return PanelIntelligenceProposal::hydrate($result);
	}

	public function dispatch(string $proposalId,PanelPolicyRequest|array $request,bool $confirmed=false,?int $expectedProposalRevision=null,?int $staleAfterSeconds=null):PanelCommandReceipt {
