	}

	/** @return array{resumed:list<array<string,mixed>>,errors:array<string,string>} */
	public function recoverStale(PanelPolicyRequest|array $request,?int $staleAfterSeconds=null,int $limit=100):array {
		$request=$this->request($request);$tenantId=$request->tenantId();if($tenantId===null){throw new \LogicException('Intelligence recovery requires an explicit tenant boundary.');}$stale=$staleAfterSeconds??$this->dispatchStaleSeconds;if($stale<0||$stale>604800){throw new \InvalidArgumentException('Intelligence recovery stale threshold is invalid.');}$limit=max(1,min(1000,$limit));$state=$this->state();$candidates=[];foreach($state['proposals']as$id=>$entry){if(!is_array($entry)||!is_array($entry['manifest']??null)){continue;}$proposal=PanelIntelligenceProposal::hydrate($entry['manifest']);if($proposal->tenantId()===$tenantId&&$proposal->status()==='dispatching'&&$this->isStale((string)($entry['dispatch']['claimed_at']??''),$stale)){$candidates[$id]=$proposal;}}uasort($candidates,static fn(PanelIntelligenceProposal $left,PanelIntelligenceProposal $right):int=>[$left->updatedAt(),$left->id()]<=>[$right->updatedAt(),$right->id()]);$resumed=[];$errors=[];foreach(array_slice($candidates,0,$limit,true)as$id=>$proposal){try{$this->authorize($request,'intelligence.proposal.recover',$proposal->tenantId(),'intelligence_proposal',$proposal->id(),$proposal->risk(),['command'=>$proposal->command()]);$command=$this->reclaimDispatch($proposal,$stale);$resumed[]=$this->receiptSummary($this->executeAndFinalize($proposal->id(),$command,$stale));}catch(\Throwable){$errors[(string)$id]='Intelligence proposal recovery failed closed.';}}return['resumed'=>$resumed,'errors'=>$errors];
	}

	/** @param array<string,mixed> $evidence */
	public function recordFeedback(string $proposalId,string $outcome,int $effectivenessBasisPoints,array $evidence,PanelPolicyRequest|array $request,string $idempotencyKey):PanelIntelligenceFeedback {
		$request=$this->request($request);$proposal=$this->proposal($proposalId);$this->assertTenant($request,$proposal->tenantId());if(!in_array($proposal->status(),['succeeded','failed','denied'],true)){throw new \LogicException('Intelligence feedback requires a completed command proposal.');}$this->authorize($request,'intelligence.feedback.record',$proposal->tenantId(),'intelligence_proposal',$proposal->id(),'low',['command'=>$proposal->command(),'command_status'=>$proposal->status(),'outcome'=>$outcome]);$outcome=strtolower(trim($outcome));if(!in_array($outcome,PanelIntelligenceFeedback::OUTCOMES,true)||$effectivenessBasisPoints<0||$effectivenessBasisPoints>10000){throw new \InvalidArgumentException('Intelligence feedback outcome or effectiveness is invalid.');}$evidence=PanelOperationsGuard::safeMetadata($evidence,256);$idempotencyHash=$this->idempotency($proposal->tenantId(),$request->actorId(),$idempotencyKey,'feedback');$fingerprint=PanelOperationsGuard::digest(['proposal_id'=>$proposal->id(),'outcome'=>$outcome,'effectiveness_basis_points'=>$effectivenessBasisPoints,'evidence_digest'=>PanelOperationsGuard::digest($evidence)]);$state=$this->state();$known=$state['idempotency']['feedback'][$idempotencyHash]??null;if(is_array($known)){if(!hash_equals((string)($known['fingerprint']??''),$fingerprint)){throw new \LogicException('Intelligence feedback idempotency key conflict.');}return$this->storedFeedback($state['feedback'][(string)$known['id']]);}$id='feedback_'.substr(hash('sha256',$idempotencyHash."\0".$fingerprint),0,40);$feedback=PanelIntelligenceFeedback::sign($id,$proposal,$outcome,$effectivenessBasisPoints,$evidence,$request->actorId(),$this->now(),$this->currentKeyId,$this->keys[$this->currentKeyId]);$stored=['manifest'=>$feedback->jsonSerialize(),'sealed'=>$this->codec->seal(['evidence'=>$feedback->evidence()],$this->feedbackContext($feedback))];
		$result=$this->mutate(function(array &$state)use($proposal,$feedback,$idempotencyHash,$fingerprint,$stored):array{$known=$state['idempotency']['feedback'][$idempotencyHash]??null;if(is_array($known)){if(!hash_equals((string)($known['fingerprint']??''),$fingerprint)){throw new \LogicException('Intelligence feedback idempotency key conflict.');}return$state['feedback'][(string)$known['id']];}if(count($state['feedback'])>=$this->maximumEntries){throw new \LengthException('Intelligence feedback retention limit is reached.');}$entry=&$this->proposalEntry($state,$proposal->id());$current=PanelIntelligenceProposal::hydrate($entry['manifest']);if(!in_array($current->status(),['succeeded','failed','denied'],true)){throw new \LogicException('Intelligence proposal is no longer eligible for feedback.');}$state['feedback'][$feedback->id()]=$stored;$entry['feedback_ids'][]=$feedback->id();$entry['feedback_ids']=array_values(array_unique($entry['feedback_ids']));sort($entry['feedback_ids'],SORT_STRING);$entry['manifest']=$current->evolve($current->status(),$current->approverHashes(),$current->revision()+1,$current->dispatchAttempts(),count($entry['feedback_ids']),$this->now(),$current->receipt(),$current->rejection())->jsonSerialize();$state['idempotency']['feedback'][$idempotencyHash]=['id'=>$feedback->id(),'fingerprint'=>$fingerprint];ksort($state['feedback'],SORT_STRING);ksort($state['idempotency']['feedback'],SORT_STRING);return$state['feedback'][$feedback->id()];},'intelligence.feedback.recorded',['feedback_id'=>$feedback->id(),'proposal_id'=>$proposal->id(),'tenant_id'=>$proposal->tenantId(),'outcome'=>$outcome]);return$this->storedFeedback($result);
	}

	public function signal(string $id):PanelIntelligenceSignal {$id=PanelOperationsGuard::identifier($id,'intelligence signal id',190);$payload=$this->state()['signals'][$id]??null;if(!is_array($payload)){throw new \OutOfBoundsException('Intelligence signal does not exist.');}return$this->storedSignal($payload);}
	public function proposal(string $id):PanelIntelligenceProposal {$id=PanelOperationsGuard::identifier($id,'intelligence proposal id',190);$entry=$this->state()['proposals'][$id]??null;if(!is_array($entry)||!is_array($entry['manifest']??null)){throw new \OutOfBoundsException('Intelligence proposal does not exist.');}return PanelIntelligenceProposal::hydrate($entry['manifest']);}
